  @override
  void initState() {
    super.initState();
    _controller = SurfaceController(catalogs: [CoreCatalogItems.asCatalog()]);
    _transport = A2uiTransportAdapter(onSend: _onSendToLLM);
    _conversation = Conversation(controller: _controller, transport: _transport);
